#!/usr/bin/env python3
# ── GENERATED by matsci-kb-kit build/build_kit.py — DO NOT EDIT (真源见 kit.yaml) ──
"""
lit_extract — lit-watch 工作流【阶段C 提取落盘】引擎。

把一篇 PDF 的「全文文字 + 正文图」提取为一张自包含 Markdown，落点由
`tools/lit_config.yaml` 的 `paths` 决定（默认如下）：

  raw/text/{文献标题}.md            —— 全文文字 + 图注 + ![](assets/...) 引用
  raw/assets/{slug}/fig_*.png       —— 每个 Figure 的实际位图

⚠️ 上面的落点**都是配置项**（`paths.text_dir` / `paths.assets_dir`），不是写死的字面量；
   本节 2026-10-10 修正：旧 docstring 声称落在 `raw/{标题}.md` 且自称
   `lit_extract_figures`，与实际行为（`raw/text/`）和真实文件名都不符——
   调用方照 docstring 找产物会找不到。

与既有 `lit_extract_to_md.py`（纯文字）不同，本脚本额外把每个图像块
按 bbox clip 渲染成 PNG 文件，并在 md 里用相对路径引用，便于 Obsidian
直接预览原图。

用法:
  python tools/lit_extract.py "<pdf路径>" [--out <md路径>] [--assets <assets根目录>]
                              [--raw-dir <md落点目录>] [--dpi 150] [--main-pages N]
                              [--no-images] [--force] [--json] [--report-json <path>]

  --json         在 stdout **只打印一行**机器可读产物报告（整行即合法 JSON，
                 前后不夹任何人类可读文字），供 lit_batch 直接解析，不必再靠
                 文件名猜产物。契约见 `extract_pdf()` 的 docstring。
  --report-json  同一份报告**原子写入**指定文件（可与 --json 同时用）。

输出（人类可读模式，即未加 --json 时）:
  - 《{标题}.md》：标题 + 元信息头 + 逐页文字（正文全量/补充材料精简）
    + 每个 Figure 的 ![](assets/{slug}/fig_X_Y.png) 与图注

退出码（lit_batch 依赖，勿改）:
  1 = PDF 文件不存在　2 = 目标不是真 PDF　4 = 目标 md 已存在且未加 --force
"""
import sys, os, re, json, argparse
from pathlib import Path

# 🔴 不再用 `sys.stdout = io.TextIOWrapper(sys.stdout.buffer, ...)`：宿主若把 stdout
#    换成没有 .buffer 的对象（测试台/嵌入环境），这一行在 **import 期**就 AttributeError，
#    连 --selftest 都跑不起来。reconfigure 在无该方法的宿主上会抛异常，故整体兜住。
try:
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    sys.stderr.reconfigure(encoding="utf-8", errors="replace")
except Exception:                            # noqa: BLE001
    pass

import fitz  # PyMuPDF

# 单篇导出图的看门狗秒数。lit_batch 以**进程内**方式调用本模块，一个坏页让 get_pixmap
# 挂死就会拖停整批；所以这里给导出图加一道超时（见 _export_figure）。
# 0 = 不限时（CLI 默认，行为与历史一致）。
PIXMAP_TIMEOUT = 0.0


class PdfExtractError(Exception):
    """带退出码语义的失败（与 CLI 退出码一一对应）。

    🔴 为什么要一个异常而不是 return None：lit_batch 以**进程内**方式调用
    `extract_pdf`，那时没有"退出码"可读。若这里只打印 + sys.exit，进程会被直接
    终止、整批中断；若返回 None，调用方又分不清"不是 PDF"与"已存在"。
    一个带 `.code` 的异常两边都能用：CLI 层转成 sys.exit(code)，
    进程内层转成台账里的 rc，语义只有一份。
    """

    def __init__(self, code, msg):
        super().__init__(msg)
        self.code = code
        self.msg = msg


# raw/pdf 与 raw/text 共用的 7 个主题分类（两侧目录名必须逐字相同）。
# 新提取件的 md 落点沿用 PDF 所在分类目录名（见 extract_pdf 的 md_path 推导）。
RAW_TEXT_CATEGORIES = (
    "01-电池与电解液", "02-AI方法与机器学习势", "03-LLM与化学智能体",
    "04-自驱动实验室与自动化", "05-催化与电催化", "06-多孔材料与网状化学",
    "99-其他与交叉领域",
)


def slugify(title):
    """文件名安全化：去非法字符，空格->'-'，保留中英文和数字。"""
    s = re.sub(r'[\\/:*?"<>|\r\n]+', ' ', title)
    s = re.sub(r'\s+', ' ', s).strip()
    s = s.replace(' ', '-')
    return s[:120] or "untitled"


def clean_page_text(text):
    lines = [ln.rstrip() for ln in text.split("\n")]
    out = []
    for ln in lines:
        if re.fullmatch(r"\d{1,3}", ln.strip()):
            continue
        out.append(ln)
    res, blank = [], 0
    for ln in out:
        if ln.strip() == "":
            blank += 1
            if blank <= 1:
                res.append("")
        else:
            blank = 0
            res.append(ln)
    return "\n".join(res).strip()


def is_supp_page(text):
    """补充材料页判定：关键词必须出现在**页首 80 字符内**。

    ⚠️ 生产路径（正文/补充材料边界扫描）必须调用本函数，不得另写内联判定：
    历史上这里存在**两份规则**——自检断言的是本函数（含页首要求），
    生产扫描用的却是宽松的 `"Supplementary Material" in t`。于是自检全绿，
    而正文里偶然引用一句 "…see Supplementary Material…" 就会被误判成 SI 起点，
    正文章节从此被整段归入"补充材料"。**一份规则，一处实现。**
    """
    return "Supplementary Material" in text and ("Supplementary" in text[:80])


def open_pdf_checked(path):
    """打开 PDF 并**硬校验**它真是 PDF；不是（或打不开）返回 None。

    🔴 为什么必须校验：`fitz.open()` 对 HTML/挑战页**不一定报错**——MuPDF 会把
    文本内容当可解析文档打开，于是 lit_fetch 魔数闸门一旦被绕过（Cloudflare 挑战页
    被落成 .pdf），本脚本会把拦截页的 HTML 提取成"全文"入库，且全程静默。
    """
    try:
        doc = fitz.open(str(path))
    except Exception:                            # noqa: BLE001
        return None
    if not getattr(doc, "is_pdf", False):
        doc.close()
        return None
    return doc


def should_overwrite(md_path, force=False):
    """是否允许写盘：目标已存在且未加 --force → 拒绝（库里「覆盖前先确认」规则）。

    旧版无条件覆盖 `raw/text/*.md`：一次重复提取就会把人工精读过的正文冲掉。
    """
    return bool(force) or not Path(md_path).exists()


def page_span_note(total, supp_start):
    """头部「共 N 页（正文…，补充材料…）」文案。

    🔴 旧版无条件拼 `补充材料 {supp_start+1}-{total}`：无补充材料时（supp_start == total）
    会输出「补充材料 3-2 页」这种**倒序区间**（实测 2-1 页），看起来像探测到了 SI。
    现在只有 `total - supp_start > 0`（确实探测到补充材料）才写该段。
    """
    sm = total - supp_start
    if sm > 0:
        return f"共 {total} 页（正文 1-{supp_start} 页，补充材料 {supp_start+1}-{total} 页）"
    return f"共 {total} 页（正文 1-{total} 页，无补充材料）"


def find_caption(page, img_rect):
    """在图像下方/上方找最近的 'Fig. X' / 'Figure X' 图注。"""
    blocks = page.get_text("blocks")
    cap_y = None
    caption = ""
    for b in blocks:
        x0, y0, x1, y1, text, *_ = b
        head = text.strip()[:12].lower()
        if head.startswith("fig") or head.startswith("figure"):
            # 图注应在图像正下方或紧邻
            dy = y0 - img_rect.y1
            if -10 < dy < 120 and (cap_y is None or abs(dy) < abs(cap_y)):
                cap_y = dy
                caption = " ".join(text.split())
    return caption


def atomic_write_text(path, text):
    """原子写文本：先写同目录 `<path>.tmp` 再 os.replace 换入。

    🔴 为什么必须原子：md 与提取台账是一对。直接 `write_text` 时进程若在写到一半
    被中断（Ctrl-C / 磁盘满 / 宿主杀进程），留下的**半截 md 仍存在于目标路径**，
    下一次运行 `should_overwrite` 会判"已存在"而拒绝重写，lit_batch 又见文件在
    就当成功 —— 于是一份**截断的提取**被永久记为已完成。
    `os.replace` 在同目录下是原子的：目标要么是完整的旧版，要么是完整的新版。

    ⚠️ 临时文件写在**目标同目录**（不是系统 TEMP）：跨卷 os.replace 会失败，
    而且 TEMP 未必可写。能写目标目录就一定能写它的 .tmp。
    """
    path = Path(path)
    tmp = str(path) + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    os.replace(tmp, path)          # 同目录 → 原子换入；旧文件被整体替换
    return path


def _export_figure(page, clip, out_path, mat):
    """渲染并保存一张图，**带看门狗**（PIXMAP_TIMEOUT 秒内必须落盘）。

    为什么不是简单的 page.get_pixmap(timeout=...)：PyMuPDF 的 timeout 参数语义是
    "超时就返回一张空白图"——那会**静默**产出一张白图并算作成功，比挂住更坏。
    这里用守护线程计时 + 超时抛 TimeoutError：宁可这一张图失败并写明原因，
    也不留一张看不出是空白的数据。
    调用方若已经用了 `--dpi` 之外的默认值（PIXMAP_TIMEOUT <= 0），
    则走**同步**路径（CLI 行为与历史完全一致，不引入线程）。
    """
    if PIXMAP_TIMEOUT <= 0:
        pix = page.get_pixmap(clip=clip, matrix=mat, alpha=False)
        pix.save(str(out_path))
        return
    import threading
    box = {}

    def _job():
        try:
            pix = page.get_pixmap(clip=clip, matrix=mat, alpha=False)
            pix.save(str(out_path))
            box["ok"] = True
        except Exception as e:                   # noqa: BLE001
            box["err"] = e

    th = threading.Thread(target=_job, daemon=True)
    th.start()
    th.join(PIXMAP_TIMEOUT)
    if th.is_alive():
        # 线程不可强杀；它是 daemon，进程退出即随之结束。此处只负责如实上报。
        raise TimeoutError(f"导出图超过 {PIXMAP_TIMEOUT:.0f}s 未完成")
    if box.get("err"):
        raise box["err"]


def _lit_defaults():
    """从 tools/lit_config.yaml 取落盘目录（相对库根 → 绝对路径）。

    🔴 修的是两个真实缺陷（2026-10-04 实测）：
      1. 旧默认值指向 **一个已不存在的旧库路径** —— 那是本库迁移前的旧位置，
         该目录**根本不存在**（实测 Test-Path=False）。
         而 SKILL.md 阶段C 的命令只传 PDF、连 --assets/--raw-dir 都不传
         ⇒ 先 mkdir 出一个**库外孤儿图目录**，再在写 md 时抛 FileNotFoundError。
      2. 写 md 前**没有对父目录 mkdir**，只要 --raw-dir 不存在就必然崩。
    """
    assets = None
    raw_dir = None
    try:
        sys.path.insert(0, str(Path(__file__).resolve().parent))
        import kb_lib as K
        cfg = K.load_lit_config()
        assets = cfg["paths"]["assets_dir"]
        raw_dir = cfg["paths"]["text_dir"]
    except Exception:                            # noqa: BLE001
        pass
    if not raw_dir:
        raw_dir = str(Path(__file__).resolve().parent.parent / "raw" / "text")
    if not assets:
        assets = str(Path(__file__).resolve().parent.parent / "raw" / "assets")
    return str(assets), str(raw_dir)


def _rel_to_vault(p):
    """绝对路径 → 相对库根（正斜杠）。取不到库根时原样返回绝对路径。

    库外路径（例如 temp 夹具里的产物）不做相对化——否则会产出
    `../../..` 这种"相对"串，看着像回链其实指不稳。此类情况直接返回原绝对路径。
    只为产物报告好看/可回链；它失败**不得**影响一次成功的提取。
    """
    try:
        sys.path.insert(0, str(Path(__file__).resolve().parent))
        import kb_lib as K
        r = os.path.relpath(str(p), K.VAULT)
        if r == os.pardir or r.startswith(os.pardir + os.sep):
            return Path(p).as_posix()            # 在库外 → 保留绝对形式
        return Path(r).as_posix()
    except Exception:                            # noqa: BLE001
        return Path(p).as_posix()


def extract_pdf(pdf, out="", assets=None, raw_dir=None, dpi=150, main_pages=None,
                no_images=False, force=False):
    """提取一篇 PDF → 落盘 md（+ 图），返回机器可读的产物报告 dict。

    **这是本模块对外的可复用 API**：lit_batch 直接 import 本模块并调用它，
    一个解释器内连做多篇（省掉每篇一次冷启动 + 一次 `import fitz`）。

    返回（全部键恒在，路径为**相对库根**的正斜杠形式）:
        {"pdf": <传入的 pdf 字符串>,
         "md":  "raw/text/xxx.md",
         "assets": "raw/assets/<slug>",          # --no-images 时为 ""
         "pages": <总页数>,
         "si_page_range": [起页, 止页]            # 1-based；无 SI 时为 []

    失败一律抛 `PdfExtractError`，其 `.code` 与 CLI 退出码同义：
        2 = 目标不是真 PDF　4 = 目标 md 已存在且未加 force
    （PDF 不存在仍是 FileNotFoundError，与历史行为一致。）

    🔴 为什么要有这份报告：lit_batch 的台账原先靠"PDF 名 == md 名"猜产物，
    而本脚本的落盘名取自 PDF 的**内嵌标题**，两者不一致时台账就把已提取的 PDF
    永久记成"待提取"（每轮重复提取、每轮再判失败）。产物路径由生产者自报，
    调用方不必猜。
    """
    pdf = Path(pdf)
    if not pdf.exists():
        raise FileNotFoundError(str(pdf))

    doc = open_pdf_checked(pdf)
    if doc is None:
        # 码 2：不是真 PDF（典型是 lit_fetch 的魔数闸门被绕过后落下的 HTML 挑战页）
        raise PdfExtractError(2, f"文件不是 PDF：{pdf}")

    if assets is None:
        assets, _ = _lit_defaults()
    if raw_dir is None:
        _, raw_dir = _lit_defaults()

    total = doc.page_count
    # ⚠️ 标题**只取文件名**（业界默认 pdf.stem），不要从首页正文猜：旧代码先算了一遍
    #    page0 文本拼出的 title，紧接着又被 pdf.stem 覆盖 —— 纯死代码，已删。
    #    保留 pdf.stem 是**有意的稳定契约**：台账/回链都按它定位，改成正文标题会让
    #    同一篇 PDF 在两次运行里落到不同文件名。
    title = pdf.stem
    slug = slugify(title)

    # 落点先算出来，好在**导出图之前**就判定是否允许覆盖（避免白写一堆图）
    # 🔴 2026-10-11：raw/text 已按 raw/pdf 的 7 分类分目录；新提取件**沿用 PDF 所在分类**，
    #    使两层结构对齐（否则新件又落回 raw/text 根，结构回潮）。仅当 PDF 位于分类子目录
    #    （形如 raw/pdf/<分类>/x.pdf）时才加一级；PDF 已在 raw/pdf 根（历史散件）则保持旧行为。
    #    显式 --out 时完全尊重调用方，不做任何改写。
    if out:
        md_path = Path(out)
    else:
        cat = Path(pdf).parent.name
        if cat in RAW_TEXT_CATEGORIES:
            md_path = Path(raw_dir) / cat / f"{title}.md"
        else:
            md_path = Path(raw_dir) / f"{title}.md"
    if not should_overwrite(md_path, force):
        # 码 4：目标 md 已存在且未加 --force。这不是"失败"，而是"已提取"——
        # lit_batch 必须把它记成 ok（how=md-exists），否则该 PDF 会永远 pending。
        doc.close()
        raise PdfExtractError(4, f"已存在，未覆盖：{md_path}")

    # 正文/补充材料边界。
    # 🔴 这里必须调 is_supp_page（自检断言的同一个函数）——旧版内联的
    #    `"Supplementary Material" in t` 少了"页首 80 字符内"的要求，
    #    正文里偶然提及该词组就会把 SI 起点提前，正文章节被整段误归 SI。
    supp_start = total  # 默认全部作为正文（无补充材料）
    for i in range(1, total):
        if is_supp_page(doc[i].get_text("text")):
            supp_start = i
            break
    if main_pages:
        supp_start = min(supp_start, main_pages)

    assets_root = Path(assets)
    paper_assets = assets_root / slug
    if not no_images:
        paper_assets.mkdir(parents=True, exist_ok=True)

    parts = []
    parts.append(f"# {title}\n")
    parts.append(f"> 提取自 PDF：{page_span_note(total, supp_start)}。"
                 f"全文文字 + 正文图（assets/{slug}/）。\n")

    def is_verbose_log(t):
        tc = t.count("TOOL CALL") + t.count("Tool returned") + t.count("[Step ")
        return tc >= 4

    # ---- 正文页：文字 + 图 ----
    skipped = 0
    fig_count = 0
    try:
        for i in range(supp_start):
            page = doc[i]
            t = clean_page_text(page.get_text("text"))
            if not t:
                continue
            parts.append(f"\n\n<!-- page {i+1} -->\n\n")
            parts.append(t)

            if no_images:
                continue

            # 找图像块（注意：TEXT_PRESERVE_WHITESPACE 会吞掉 type==1 图像块，勿加）
            blocks = page.get_text("dict").get("blocks", [])
            img_blocks = [b for b in blocks if b.get("type") == 1]
            # ⚠️ 旧版此处还有 `page_imgs = page.get_images(full=True)`——从没被读过，
            #    却要在图多的 PDF 上把全部图像 xref 枚举一遍（实测是主要耗时之一）。已删。
            seen_xref = set()
            for ib in img_blocks:
                bbox = fitz.Rect(ib["bbox"])
                xref = ib.get("xref") or 0
                if xref in seen_xref:
                    continue
                w, h = bbox.width, bbox.height
                if w < 20 or h < 20:  # 跳过装饰性小图
                    continue
                # 通过额外进位判断是否为正文 Figure（排除页眉页脚 logo）
                if bbox.y0 < 40 or bbox.y1 > page.rect.height - 40:
                    continue

                caption = find_caption(page, bbox)
                fig_count += 1
                fname = f"fig_p{i+1}_{fig_count}.png"
                # clip 该区域 + 周边 4pt 边距，高 DPI 渲染
                clip = fitz.Rect(bbox.x0 - 8, bbox.y0 - 8, bbox.x1 + 8, bbox.y1 + 8)
                zoom = dpi / 72.0
                mat = fitz.Matrix(zoom, zoom)
                try:
                    _export_figure(page, clip, paper_assets / fname, mat)
                    seen_xref.add(xref)
                    parts.append(f"\n![图 {i+1}-{fig_count}](assets/{slug}/{fname})")
                    if caption:
                        parts.append(f"\n*{caption}*")
                except Exception as e:                # noqa: BLE001
                    print(f"[warn] 导出图 {fname} 失败: {e}", file=sys.stderr)

        # ---- 补充材料：全量但跳过 verbose 日志页 ----
        kept_sm = 0
        for i in range(supp_start, total):
            page = doc[i]
            t = page.get_text("text")
            if is_verbose_log(t) or not t.strip():
                skipped += 1
                continue
            t = clean_page_text(t)
            kept_sm += 1
            parts.append(f"\n\n<!-- SM page {i+1} -->\n\n")
            parts.append(t)
            # 补充材料里的图仅保留图注引用（文字层面），不导出
    finally:
        # 任何异常（含导出图看门狗超时）都必须关文档，否则进程内批量调用会累积句柄
        doc.close()

    text = "".join(parts)
    # md_path 已在开头算好并做过覆盖门禁（见上），此处不再重复推导
    # 旧版缺这一步：只要父目录不存在就 FileNotFoundError（而默认父目录曾经不存在）
    md_path.parent.mkdir(parents=True, exist_ok=True)
    atomic_write_text(md_path, text)

    si_range = [supp_start + 1, total] if total - supp_start > 0 else []
    return {
        "pdf": str(pdf),
        "md": _rel_to_vault(md_path),
        "assets": _rel_to_vault(paper_assets) if not no_images else "",
        "pages": total,
        "si_page_range": si_range,
        # 仅供 --json / --report-json 之外的调用方参考（不算契约的一部分）
        "_text_len": len(text),
        "_kept_sm": kept_sm,
        "_skipped": skipped,
        "_figs": 0 if no_images else fig_count,
        "_md_abs": str(md_path),
    }


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    钉住本脚本的三条纯文本规则：文件名安全化、页码行剔除/空行折叠、
    补充材料页判定。这三条一旦错，产物会**静默**变成不可用文件名或脏正文。
    """
    ok = True

    # ---- slugify：非法字符必须清掉（Windows 文件名安全）----
    cases = [
        ("A/B:C*D?E\"F<G>H|I", None, "含全部 Windows 非法字符"),
        ("  Multiple   spaces  ", "Multiple-spaces", "连续空白折叠为单个 -"),
        ("", "untitled", "反例 空标题兜底"),
        ("中文标题 test", "中文标题-test", "中英混排保留"),
    ]
    for src, want, label in cases:
        got = slugify(src)
        if want is None:
            good = not re.search(r'[\\/:*?"<>|\r\n]', got) and got
            print(f"  [{'ok' if good else 'FAIL'}] slugify {label} -> {got!r}")
            ok = ok and bool(good)
        else:
            mark = "ok" if got == want else "FAIL"
            print(f"  [{mark}] slugify {label} -> {got!r}")
            ok = ok and got == want
    # 长度上限
    got = slugify("x" * 500)
    good = len(got) <= 120
    print(f"  [{'ok' if good else 'FAIL'}] slugify 长度上限 120 -> {len(got)}")
    ok = ok and good

    # ---- clean_page_text：纯数字行（页码）剔除、连续空行折叠为 1 ----
    got = clean_page_text("line1\n\n\n\nline2\n42\n")
    good = got == "line1\n\nline2"
    print(f"  [{'ok' if good else 'FAIL'}] clean_page_text 剔页码+折叠空行 -> {got!r}")
    ok = ok and good
    # 反例：正文里的多位数不得被当页码删（页码只认 1–3 位）
    got = clean_page_text("1234 is a value")
    good = "1234" in got
    print(f"  [{'ok' if good else 'FAIL'}] 反例 4 位数正文不被当页码 -> {got!r}")
    ok = ok and good

    # ---- is_supp_page：正例 + 反例（关键词须出现在开头 80 字符内）----
    good_txt = "Supplementary Material\nmore text"
    got = is_supp_page(good_txt)
    print(f"  [{'ok' if got else 'FAIL'}] 正例 补充材料页 -> {got}")
    ok = ok and got
    # 反例：关键词出现在很后面（正文中偶然提及引用）不得判为补充材料页
    late = "x" * 200 + "Supplementary Material"
    got = is_supp_page(late)
    print(f"  [{'ok' if not got else 'FAIL'}] 反例 关键词在 80 字符后不判真 -> {got}")
    ok = ok and not got
    got = is_supp_page("ordinary page")
    print(f"  [{'ok' if not got else 'FAIL'}] 反例 普通页 -> {got}")
    ok = ok and not got

    # ---- 生产边界扫描必须**用同一个函数**（正文里偶提该词组不得当 SI 起点）----
    # 🔴 这是回归夹具：旧版生产路径写成内联的 `"Supplementary Material" in t`，
    #    自检断言 is_supp_page 才通过 —— 规则分叉，自检看不见真路径。
    #    造法：先铺够 80 字符正文，再让该词组出现在其后（页首区域内不得命中）。
    body_page = "正文若干" + "x" * 90 + "详见 Supplementary Material 第 3 节"
    got = is_supp_page(body_page)
    print(f"  [{'ok' if not got else 'FAIL'}] 反例 正文提及该词组 → 不作 SI 起点 -> {got}")
    ok = ok and not got

    # ---- open_pdf_checked：真 PDF 放行，HTML（含 %PDF 字样）必须拦下 ----
    # 🔴 反例是关键：lit_fetch 魔数闸门若被绕过，挑战页会带着 %PDF 字样落成 .pdf，
    #    这里若不拦，就会被当成"全文"提取入库（静默污染）。
    #    夹具写在本脚本目录下（用唯一名，用完即删）——宿主 TEMP 与新建子目录可能不可写。
    import uuid
    test_dir = Path(__file__).resolve().parent
    stem_u = "_selftest_" + uuid.uuid4().hex[:8]
    try:
        real = test_dir / f"{stem_u}_real.pdf"
        d = fitz.open()
        d.new_page()
        d.save(str(real))
        d.close()
        got = open_pdf_checked(real)
        good = got is not None
        print(f"  [{'ok' if good else 'FAIL'}] 正例 真 PDF 通过硬校验 -> {good}")
        ok = ok and good
        if got is not None:
            got.close()

        fake = test_dir / f"{stem_u}_fake.pdf"
        fake.write_bytes(b"<html><body>cf challenge %PDF-1.7 not a pdf</body></html>")
        got = open_pdf_checked(fake)
        good = got is None
        print(f"  [{'ok' if good else 'FAIL'}] 反例 HTML（内嵌 %PDF 字样）被拦下 -> {got is None}")
        ok = ok and good
    finally:
        for f in test_dir.glob(f"{stem_u}_*"):
            f.unlink(missing_ok=True)

    # ---- should_overwrite：已存在时默认不覆盖，--force 才允许 ----
    ex = test_dir / f"{stem_u}_exists.md"
    try:
        ex.write_text("x", encoding="utf-8")
        good = (should_overwrite(ex, False) is False
                and should_overwrite(ex, True) is True
                and should_overwrite(test_dir / f"{stem_u}_nope.md", False) is True)
        print(f"  [{'ok' if good else 'FAIL'}] 已存在默认不覆盖 / --force 覆盖 / 不存在可写 -> {good}")
        ok = ok and good
    finally:
        ex.unlink(missing_ok=True)

    # ---- page_span_note：无补充材料时不得输出倒序区间 ----
    note_none = page_span_note(10, 10)
    good = ("无补充材料" in note_none) and ("补充材料 11" not in note_none)
    print(f"  [{'ok' if good else 'FAIL'}] 无 SI → 不写补充材料段 -> {note_none!r}")
    ok = ok and good
    note_sm = page_span_note(10, 7)
    good = "补充材料 8-10 页" in note_sm
    print(f"  [{'ok' if good else 'FAIL'}] 有 SI → 写补充材料区间 -> {note_sm!r}")
    ok = ok and good

    # ---- atomic_write_text + extract_pdf 端到端（真 PDF → 报告 → 码 4）----
    # 🔴 端到端才是真夹具：只测纯函数时，"md 半截落盘 + 台账记成功"这类
    #    失效形态（本次修的两处）完全测不到。
    import shutil
    import tempfile
    work = Path(tempfile.gettempdir()) / ("_lit_extract_selftest_" + uuid.uuid4().hex[:8])
    try:
        raw_dir = work / "raw" / "text"
        ast_dir = work / "raw" / "assets"
        raw_dir.mkdir(parents=True, exist_ok=True)
        src = work / "sample-paper.pdf"
        d = fitz.open()
        pg = d.new_page()
        pg.insert_text((72, 72), "A sample title")
        d.new_page().insert_text((72, 72), "Supplementary Material")
        d.save(str(src))
        d.close()

        rep = extract_pdf(src, raw_dir=str(raw_dir), assets=str(ast_dir), no_images=True)
        good = (rep["pages"] == 2 and rep["si_page_range"] == [2, 2]
                and Path(rep["_md_abs"]).exists()
                and "sample-paper" in rep["md"])
        print(f"  [{'ok' if good else 'FAIL'}] extract_pdf 端到端（页数/SI 区间/落盘）-> "
              f"{rep['pages']} 页 SI={rep['si_page_range']} md={rep['md']}")
        ok = ok and good

        # 反例：目标已存在 → 必须抛码 4（lit_batch 靠它把 PDF 记成"已提取"）
        code = None
        try:
            extract_pdf(src, raw_dir=str(raw_dir), assets=str(ast_dir), no_images=True)
        except PdfExtractError as e:
            code = e.code
        good = code == 4
        print(f"  [{'ok' if good else 'FAIL'}] 反例 目标已存在 → 抛码 4 -> {code}")
        ok = ok and good
        # 正例：--force 后必须能覆盖
        rep2 = extract_pdf(src, raw_dir=str(raw_dir), assets=str(ast_dir),
                           no_images=True, force=True)
        good = Path(rep2["_md_abs"]).exists()
        print(f"  [{'ok' if good else 'FAIL'}] force=True 覆盖成功 -> {good}")
        ok = ok and good

        # 反例：HTML 冒充 PDF → 必须抛码 2
        bad = work / "challenge.pdf"
        bad.write_bytes(b"<html>%PDF-1.7 challenge</html>")
        code = None
        try:
            extract_pdf(bad, raw_dir=str(raw_dir), assets=str(ast_dir), no_images=True)
        except PdfExtractError as e:
            code = e.code
        good = code == 2
        print(f"  [{'ok' if good else 'FAIL'}] 反例 HTML → 抛码 2 -> {code}")
        ok = ok and good

        # 原子写：写完不得残留 .tmp
        stray = list(raw_dir.glob("*.tmp"))
        good = not stray
        print(f"  [{'ok' if good else 'FAIL'}] 原子写后无 .tmp 残留 -> {[p.name for p in stray]}")
        ok = ok and good
    finally:
        shutil.rmtree(work, ignore_errors=True)

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    _assets_def, _raw_def = _lit_defaults()
    ap = argparse.ArgumentParser()
    ap.add_argument("pdf", nargs="?", default="", help="PDF 路径")
    ap.add_argument("--out", default="", help="输出的 md 路径（默认 <text_dir>/{标题}.md）")
    ap.add_argument("--assets", default=_assets_def,
                    help=f"assets 根目录（默认 {_assets_def}）")
    ap.add_argument("--raw-dir", default=_raw_def,
                    help=f"全文 md 落盘目录（默认 {_raw_def}）")
    ap.add_argument("--dpi", type=int, default=150)
    ap.add_argument("--main-pages", type=int, default=None)
    ap.add_argument("--no-images", action="store_true",
                    help="只提取文字，不导出图")
    ap.add_argument("--force", action="store_true",
                    help="目标 md 已存在时允许覆盖（默认拒绝，库里规则：覆盖前先确认）")
    ap.add_argument("--json", action="store_true",
                    help="stdout 只打印一行产物报告 JSON（供 lit_batch 解析；不夹别的文字）")
    ap.add_argument("--report-json", default="",
                    help="把同一份产物报告原子写入该路径（可与 --json 同时用）")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    args = ap.parse_args()

    if args.selftest:
        return selftest()
    # 注：`pdf` 原先为位置必填，会让 --selftest 无法单独运行，故改为此处校验
    if not args.pdf:
        ap.error("必须提供 PDF 路径")

    try:
        rep = extract_pdf(args.pdf, out=args.out, assets=args.assets,
                          raw_dir=args.raw_dir, dpi=args.dpi,
                          main_pages=args.main_pages, no_images=args.no_images,
                          force=args.force)
    except FileNotFoundError:
        print(f"❌ PDF 不存在: {args.pdf}", file=sys.stderr)
        return 1
    except PdfExtractError as e:
        print(f"❌ {e.msg}", file=sys.stderr)
        if e.code == 2:
            print("   （lit_fetch 的魔数闸门可能被绕过；请确认拿到的不是 HTML 挑战页）",
                  file=sys.stderr)
        elif e.code == 4:
            print("   （要覆盖请加 --force）", file=sys.stderr)
        return e.code

    # 报告：文件 → 原子写；stdout → 单独一行（人类可读输出随之让位）
    if args.report_json:
        p = Path(args.report_json)
        p.parent.mkdir(parents=True, exist_ok=True)
        atomic_write_text(p, json.dumps(rep, ensure_ascii=False))
    if args.json:
        print(json.dumps(rep, ensure_ascii=False))
        return 0

    print(f"[done] {rep['_md_abs']}")
    print(f"        图 {rep['_figs']} 张  →  {rep['assets'] or '(跳过)'}")
    print(f"        字 {rep['_text_len']}  |  补充材料保留 {rep['_kept_sm']} 页, "
          f"跳过 {rep['_skipped']} 页")
    return 0


if __name__ == "__main__":
    sys.exit(main())
